import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { NotFoundError, TodoError, UsageError } from '../src/errors.js';
import {
  MAX_TEXT_LENGTH,
  addTodo,
  completeTodo,
  createEmptyState,
  deleteTodo,
  normalizeText,
  parseId,
} from '../src/todos.js';

const FIXED_NOW = new Date('2026-01-02T03:04:05.678Z');

function stateWith(...todos) {
  const nextId = todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
  return { nextId, todos };
}

function todo(id, overrides = {}) {
  return { id, text: `Todo ${id}`, completed: false, createdAt: FIXED_NOW.toISOString(), ...overrides };
}

describe('normalizeText', () => {
  it('trims surrounding whitespace', () => {
    assert.equal(normalizeText('  Buy groceries \t'), 'Buy groceries');
  });

  it('applies NFC so a decomposed accent is stored as one code point', () => {
    assert.equal(normalizeText('café'), 'café');
  });

  it('rejects an empty string', () => {
    assert.throws(() => normalizeText(''), { name: 'UsageError', message: /cannot be empty/ });
  });

  it('rejects whitespace-only text', () => {
    assert.throws(() => normalizeText(' \t \n '), { name: 'UsageError', message: /cannot be empty/ });
  });

  it('rejects a newline inside the text', () => {
    assert.throws(() => normalizeText('line one\nline two'), { name: 'UsageError', message: /control characters/ });
  });

  it('rejects non-string input', () => {
    for (const value of [undefined, null, 42, ['a']]) {
      assert.throws(() => normalizeText(value), UsageError, `expected ${String(value)} to be rejected`);
    }
  });

  it('accepts text exactly at the maximum length', () => {
    const text = 'a'.repeat(MAX_TEXT_LENGTH);
    assert.equal(normalizeText(text), text);
  });

  it('rejects text one character over the maximum length', () => {
    assert.throws(() => normalizeText('a'.repeat(MAX_TEXT_LENGTH + 1)), {
      name: 'UsageError',
      message: new RegExp(`${MAX_TEXT_LENGTH + 1} characters \\(maximum ${MAX_TEXT_LENGTH}\\)`),
    });
  });

  it('counts an emoji as one character, not two UTF-16 units', () => {
    const text = '😀'.repeat(MAX_TEXT_LENGTH);
    assert.equal(text.length, MAX_TEXT_LENGTH * 2);
    assert.equal(normalizeText(text), text);
  });

  it('honours a custom maxLength', () => {
    assert.equal(normalizeText('abc', { maxLength: 3 }), 'abc');
    assert.throws(() => normalizeText('abcd', { maxLength: 3 }), UsageError);
  });
});

describe('parseId', () => {
  const valid = [
    ['1', 1],
    ['42', 42],
    [' 7 ', 7],
    ['007', 7],
    [String(Number.MAX_SAFE_INTEGER), Number.MAX_SAFE_INTEGER],
  ];
  for (const [input, expected] of valid) {
    it(`parses ${JSON.stringify(input)} as ${expected}`, () => {
      assert.equal(parseId(input), expected);
    });
  }

  const invalid = ['0', '-1', '1.5', 'abc', '1e3', '0x10', '', '   ', '1 2', '+3', '9007199254740992'];
  for (const input of invalid) {
    it(`rejects ${JSON.stringify(input)}`, () => {
      assert.throws(() => parseId(input), { name: 'UsageError', message: /Invalid id/ });
    });
  }

  it('rejects a non-string id', () => {
    assert.throws(() => parseId(undefined), { name: 'UsageError', message: /must be a string/ });
    assert.throws(() => parseId(3), UsageError);
  });
});

describe('addTodo', () => {
  it('assigns nextId, stores pending status and the creation time', () => {
    const { state, todo: added, changed } = addTodo(createEmptyState(), 'Buy groceries', { now: FIXED_NOW });
    assert.deepEqual(added, { id: 1, text: 'Buy groceries', completed: false, createdAt: '2026-01-02T03:04:05.678Z' });
    assert.deepEqual(state, { nextId: 2, todos: [added] });
    assert.equal(changed, true);
  });

  it('appends after existing todos and increments the id', () => {
    const { state } = addTodo(stateWith(todo(1), todo(2)), 'Third', { now: FIXED_NOW });
    assert.deepEqual(state.todos.map((t) => t.id), [1, 2, 3]);
    assert.equal(state.nextId, 4);
  });

  it('does not modify the input state', () => {
    const input = stateWith(todo(1));
    const snapshot = structuredClone(input);
    addTodo(input, 'Another');
    assert.deepEqual(input, snapshot);
  });

  it('rejects blank text without producing a todo', () => {
    assert.throws(() => addTodo(createEmptyState(), '   '), UsageError);
  });

  it('refuses to assign an id beyond the largest safe integer', () => {
    const exhausted = { nextId: Number.MAX_SAFE_INTEGER + 1, todos: [] };
    assert.throws(() => addTodo(exhausted, 'Too many'), (error) => error instanceof TodoError && /safe integer/.test(error.message));
  });
});

describe('completeTodo', () => {
  it('marks the matching todo as completed and leaves others alone', () => {
    const { state, todo: completed, changed } = completeTodo(stateWith(todo(1), todo(2)), 2);
    assert.equal(changed, true);
    assert.equal(completed.completed, true);
    assert.deepEqual(state.todos.map((t) => t.completed), [false, true]);
  });

  it('returns changed=false and the same state when the todo is already completed', () => {
    const input = stateWith(todo(1, { completed: true }));
    const result = completeTodo(input, 1);
    assert.equal(result.changed, false);
    assert.equal(result.state, input);
  });

  it('throws NotFoundError for an unknown id', () => {
    assert.throws(() => completeTodo(stateWith(todo(1)), 5), (error) => error instanceof NotFoundError && error.id === 5);
  });

  it('throws NotFoundError when the list is empty', () => {
    assert.throws(() => completeTodo(createEmptyState(), 1), NotFoundError);
  });

  it('does not modify the input state', () => {
    const input = stateWith(todo(1));
    const snapshot = structuredClone(input);
    completeTodo(input, 1);
    assert.deepEqual(input, snapshot);
  });
});

describe('deleteTodo', () => {
  it('removes only the matching todo and keeps the order of the rest', () => {
    const { state, todo: removed } = deleteTodo(stateWith(todo(1), todo(2), todo(3)), 2);
    assert.equal(removed.id, 2);
    assert.deepEqual(state.todos.map((t) => t.id), [1, 3]);
  });

  it('keeps nextId so a deleted id is not reused', () => {
    const { state } = deleteTodo(stateWith(todo(1), todo(2)), 2);
    assert.equal(state.nextId, 3);
    assert.equal(addTodo(state, 'New').todo.id, 3);
  });

  it('throws NotFoundError for an unknown id', () => {
    assert.throws(() => deleteTodo(stateWith(todo(1)), 2), NotFoundError);
  });

  it('does not modify the input state', () => {
    const input = stateWith(todo(1), todo(2));
    const snapshot = structuredClone(input);
    deleteTodo(input, 1);
    assert.deepEqual(input, snapshot);
  });
});

