import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { StorageError } from '../src/errors.js';
import { parseState } from '../src/schema.js';

const SOURCE = '/tmp/todos.json';

function todo(id, overrides = {}) {
  return { id, text: `Todo ${id}`, completed: false, createdAt: '2026-01-02T03:04:05.678Z', ...overrides };
}

describe('parseState', () => {
  it('accepts the { nextId, todos } shape written by the app', () => {
    const data = { nextId: 5, todos: [todo(1), todo(3, { completed: true })] };
    assert.deepEqual(parseState(data, SOURCE), data);
  });

  it('accepts a bare array and derives nextId from the largest id', () => {
    assert.deepEqual(parseState([todo(4), todo(2)], SOURCE), { nextId: 5, todos: [todo(4), todo(2)] });
  });

  it('treats an empty array as an empty list starting at id 1', () => {
    assert.deepEqual(parseState([], SOURCE), { nextId: 1, todos: [] });
  });

  it('derives nextId when the object omits it', () => {
    assert.equal(parseState({ todos: [todo(7)] }, SOURCE).nextId, 8);
  });

  it('raises a nextId that is not above every existing id, preventing duplicate ids', () => {
    assert.equal(parseState({ nextId: 2, todos: [todo(1), todo(9)] }, SOURCE).nextId, 10);
  });

  it('accepts timestamps with a numeric UTC offset', () => {
    const data = { nextId: 2, todos: [todo(1, { createdAt: '2026-01-02T03:04:05+02:00' })] };
    assert.deepEqual(parseState(data, SOURCE), data);
  });

  it('keeps unknown todo fields so rewriting the file does not drop them', () => {
    const [parsed] = parseState({ nextId: 2, todos: [todo(1, { priority: 'high' })] }, SOURCE).todos;
    assert.equal(parsed.priority, 'high');
  });

  it('returns todo objects that are copies of the input', () => {
    const input = { nextId: 2, todos: [todo(1)] };
    const parsed = parseState(input, SOURCE);
    parsed.todos[0].completed = true;
    assert.equal(input.todos[0].completed, false);
  });

  for (const [label, data] of [
    ['null', null],
    ['a string', 'todos'],
    ['a number', 3],
  ]) {
    it(`rejects top-level ${label} with the file path in the message`, () => {
      assert.throws(() => parseState(data, SOURCE), (error) => error instanceof StorageError && error.message.startsWith(SOURCE));
    });
  }

  it('rejects an object whose "todos" is not an array', () => {
    assert.throws(() => parseState({ nextId: 1, todos: {} }, SOURCE), { name: 'StorageError', message: /"todos" must be an array/ });
  });

  const invalidTodos = [
    ['a non-object entry', 'buy milk', /must be an object/],
    ['id 0', todo(0), /"id": expected a positive integer, got 0/],
    ['a string id', todo('1'), /"id": expected a positive integer, got "1"/],
    ['a fractional id', todo(1.5), /"id"/],
    ['empty text', todo(1, { text: '  ' }), /"text": expected a non-empty string/],
    ['numeric text', todo(1, { text: 5 }), /"text"/],
    ['a string completed flag', todo(1, { completed: 'yes' }), /"completed": expected a boolean, got "yes"/],
    ['a non-ISO date', todo(1, { createdAt: 'yesterday' }), /"createdAt": expected an ISO 8601 timestamp/],
    ['an impossible date', todo(1, { createdAt: '2026-13-45T99:00:00Z' }), /"createdAt"/],
    ['a missing createdAt', todo(1, { createdAt: undefined }), /"createdAt".*got undefined/],
  ];
  for (const [label, entry, message] of invalidTodos) {
    it(`rejects a todo with ${label}, naming its index`, () => {
      assert.throws(() => parseState({ nextId: 3, todos: [todo(1), entry] }, SOURCE), (error) => {
        assert.ok(error instanceof StorageError);
        assert.match(error.message, /todo at index 1/);
        assert.match(error.message, message);
        return true;
      });
    });
  }

  it('rejects duplicate ids', () => {
    assert.throws(() => parseState([todo(1), todo(1)], SOURCE), { name: 'StorageError', message: /index 1 reuses id 1/ });
  });

  for (const nextId of [0, -1, '3', 1.5]) {
    it(`rejects nextId ${JSON.stringify(nextId)}`, () => {
      assert.throws(() => parseState({ nextId, todos: [] }, SOURCE), { name: 'StorageError', message: /"nextId" must be a positive integer/ });
    });
  }
});

