import { randomBytes } from 'node:crypto';
import { open, readFile, rename, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';
import { StorageError } from './errors.js';
import { parseState } from './schema.js';
import { createEmptyState } from './todos.js';

/** @typedef {import('./todos.js').TodoState} TodoState */
/** @typedef {import('./todos.js').TodoResult} TodoResult */

/**
 * @typedef {object} LockOptions
 * @property {number} [timeoutMs] give up waiting for another process after this long
 * @property {number} [retryMs] wait between attempts to take the lock
 * @property {number} [staleMs] a lock older than this is treated as abandoned
 */

/** Name of the data file, resolved against the working directory. */
export const TODOS_FILENAME = 'todos.json';

/** Lock settings used when the caller does not override them. */
export const DEFAULT_LOCK_OPTIONS = Object.freeze({ timeoutMs: 5000, retryMs: 25, staleMs: 30_000 });

/** Upper bound on a single read or write of todos.json, so a hung filesystem cannot block forever. */
export const IO_TIMEOUT_MS = 10_000;

const LOCK_HELD = 'held';
const LOCK_RELEASED = 'released';
const LOCK_STALE = 'stale';

/**
 * @param {string} cwd
 * @returns {string} absolute path of todos.json inside `cwd`
 */
export function resolveTodosPath(cwd) {
  return path.resolve(cwd, TODOS_FILENAME);
}

/**
 * A missing or empty file is an empty list. Invalid content raises an error
 * rather than being replaced, so a typo in a hand-edited file never costs data.
 * @param {string} filePath
 * @returns {Promise<TodoState>}
 * @throws {StorageError}
 */
export async function loadTodos(filePath) {
  let contents;
  try {
    contents = await readFile(filePath, { encoding: 'utf8', signal: AbortSignal.timeout(IO_TIMEOUT_MS) });
  } catch (error) {
    if (error.code === 'ENOENT') {
      return createEmptyState();
    }
    throw new StorageError(`Could not read ${filePath}: ${error.message}`, { cause: error });
  }

  // Some Windows editors prepend a byte order mark, which JSON.parse rejects.
  const json = contents.replace(/^﻿/, '');
  if (json.trim() === '') {
    return createEmptyState();
  }
  let data;
  try {
    data = JSON.parse(json);
  } catch (error) {
    throw new StorageError(
      `${filePath} is not valid JSON (${error.message}). The file was left unchanged; fix or remove it.`,
      { cause: error },
    );
  }
  return parseState(data, filePath);
}

/**
 * Writes to a temporary file in the same directory, flushes it, then renames
 * it over todos.json. Readers see either the old file or the new one, never
 * a partial write.
 * @param {string} filePath
 * @param {TodoState} state
 * @returns {Promise<void>}
 * @throws {StorageError}
 */
export async function saveTodos(filePath, state) {
  const tempPath = `${filePath}.${process.pid}.${randomBytes(6).toString('hex')}.tmp`;
  const json = `${JSON.stringify({ nextId: state.nextId, todos: state.todos }, null, 2)}\n`;
  try {
    const handle = await open(tempPath, 'wx');
    try {
      await handle.writeFile(json, { encoding: 'utf8', signal: AbortSignal.timeout(IO_TIMEOUT_MS) });
      await handle.sync();
    } finally {
      await handle.close();
    }
    await rename(tempPath, filePath);
  } catch (error) {
    try {
      await rm(tempPath, { force: true });
    } catch (cleanupError) {
      throw new StorageError(
        `Could not write ${filePath}: ${error.message} (removing ${tempPath} also failed: ${cleanupError.message})`,
        { cause: error },
      );
    }
    throw new StorageError(`Could not write ${filePath}: ${error.message}`, { cause: error });
  }
}

/**
 * Runs `fn` while holding `<filePath>.lock`, so concurrent CLI invocations
 * cannot interleave their read-modify-write cycles and lose updates. A lock
 * whose owner process has exited, or that is older than `staleMs`, is taken over.
 * @template T
 * @param {string} filePath
 * @param {() => Promise<T>} fn
 * @param {LockOptions} [options]
 * @returns {Promise<T>}
 * @throws {StorageError} when the lock cannot be taken within `timeoutMs`
 */
export async function withFileLock(filePath, fn, options = {}) {
  const settings = { ...DEFAULT_LOCK_OPTIONS, ...options };
  const lockPath = `${filePath}.lock`;
  const handle = await acquireLock(lockPath, settings);
  try {
    try {
      await handle.writeFile(`${process.pid}\n`, 'utf8');
    } finally {
      await handle.close();
    }
    return await fn();
  } finally {
    await rm(lockPath, { force: true });
  }
}

/**
 * Loads the todos, applies `mutate`, and saves the result if `changed` is
 * true, all under the file lock.
 * @param {string} filePath
 * @param {(state: TodoState) => TodoResult} mutate
 * @param {LockOptions} [lockOptions]
 * @returns {Promise<TodoResult>}
 */
export async function updateTodos(filePath, mutate, lockOptions) {
  return withFileLock(
    filePath,
    async () => {
      const result = mutate(await loadTodos(filePath));
      if (result.changed) {
        await saveTodos(filePath, result.state);
      }
      return result;
    },
    lockOptions,
  );
}

async function acquireLock(lockPath, { timeoutMs, retryMs, staleMs }) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      return await open(lockPath, 'wx');
    } catch (error) {
      if (error.code !== 'EEXIST') {
        throw new StorageError(`Could not create lock file ${lockPath}: ${error.message}`, { cause: error });
      }
    }

    const lockState = await inspectLock(lockPath, staleMs);
    if (lockState === LOCK_STALE) {
      await rm(lockPath, { force: true });
    }
    if (lockState !== LOCK_HELD) {
      continue;
    }
    if (Date.now() >= deadline) {
      throw new StorageError(
        `Timed out after ${timeoutMs} ms waiting for ${lockPath}. ` +
          'If no other todo command is running, delete that file and try again.',
      );
    }
    await delay(retryMs);
  }
}

async function inspectLock(lockPath, staleMs) {
  let info;
  let contents;
  try {
    info = await stat(lockPath);
    contents = await readFile(lockPath, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      return LOCK_RELEASED;
    }
    throw new StorageError(`Could not inspect lock file ${lockPath}: ${error.message}`, { cause: error });
  }
  if (Date.now() - info.mtimeMs > staleMs) {
    return LOCK_STALE;
  }
  // An empty file means the owner has created the lock but not yet written its pid.
  const pid = Number.parseInt(contents, 10);
  return Number.isSafeInteger(pid) && pid > 0 && !isProcessAlive(pid) ? LOCK_STALE : LOCK_HELD;
}

function isProcessAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    // EPERM: the process exists but belongs to another user. ESRCH: no such process.
    return error.code === 'EPERM';
  }
}

