import { execFile, spawnSync } from 'node:child_process';
import { mkdtemp, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { run } from '../src/cli.js';

export const INDEX_PATH = fileURLToPath(new URL('../index.js', import.meta.url));

const CLI_TIMEOUT_MS = 15_000;

/** Creates an empty directory that is removed when test `t` finishes. */
export async function makeTempDir(t) {
  const dir = await mkdtemp(path.join(os.tmpdir(), 'todo-cli-test-'));
  t.after(() => rm(dir, { recursive: true, force: true }));
  return dir;
}

/** Runs `node index.js ...args` as a child process in `cwd`. */
export function runCli(args, { cwd }) {
  return new Promise((resolve, reject) => {
    execFile(
      process.execPath,
      [INDEX_PATH, ...args],
      { cwd, timeout: CLI_TIMEOUT_MS, encoding: 'utf8' },
      (error, stdout, stderr) => {
        // A numeric code means the CLI ran and exited non-zero; anything else is a spawn failure or timeout.
        if (error && typeof error.code !== 'number') {
          reject(new Error(`node index.js ${args.join(' ')} did not exit normally: ${error.message}`, { cause: error }));
          return;
        }
        resolve({ code: error ? error.code : 0, stdout, stderr });
      },
    );
  });
}

/** Runs the CLI in this process with captured output, for tests that need custom options. */
export async function runInProcess(args, { cwd, ...options }) {
  const stdout = createCapture();
  const stderr = createCapture();
  const code = await run(args, { cwd, stdout, stderr, ...options });
  return { code, stdout: stdout.text(), stderr: stderr.text() };
}

function createCapture() {
  const chunks = [];
  return {
    write(chunk) {
      chunks.push(String(chunk));
      return true;
    },
    text: () => chunks.join(''),
  };
}

export async function readTodosFile(dir) {
  return JSON.parse(await readFile(path.join(dir, 'todos.json'), 'utf8'));
}

export async function writeTodosFile(dir, contents) {
  const text = typeof contents === 'string' ? contents : JSON.stringify(contents);
  await writeFile(path.join(dir, 'todos.json'), text, 'utf8');
}

export async function listDir(dir) {
  return (await readdir(dir)).sort();
}

/** Returns the pid of a process that has already exited. */
export function deadPid() {
  const result = spawnSync(process.execPath, ['-e', '']);
  if (result.error) {
    throw new Error(`Could not spawn a short-lived process: ${result.error.message}`, { cause: result.error });
  }
  return result.pid;
}

