export async function run(argv, options = {}) {
  const { cwd = process.cwd(), stdout = process.stdout, stderr = process.stderr, now = () => new Date(), lock } = options;
  const [name, ...args] = argv;

  if (name === undefined) {
    stderr.write(`${usage()}\n`);
    return EXIT_CODES.USAGE;
  }

  try {
    const command = resolveCommand(name, args);
    await command.run({ args, filePath: resolveTodosPath(cwd), stdout, now, lock });
    return EXIT_CODES.SUCCESS;
  } catch (error) {
