    const result = await runCli(['add', 'Buy groceries'], { cwd: dir });
    assert.equal(result.code, 0, result.stderr);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');

    const { nextId, todos } = await readTodosFile(dir);
    assert.equal(nextId, 2);
    assert.equal(todos.length, 1);
    const [todo] = todos;
    assert.deepEqual(Object.keys(todo).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(todo.id, 1);
    assert.equal(todo.text, 'Buy groceries');
    assert.equal(todo.completed, false);
    assert.match(todo.createdAt, ISO_TIMESTAMP);
    assert.ok(Date.parse(todo.createdAt) >= before - 1000, 'createdAt should be the current time');
  });

  it('assigns auto-incrementing ids', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'First', 'Second', 'Third');
    const { todos } = await readTodosFile(dir);
    assert.deepEqual(todos.map((todo) => [todo.id, todo.text]), [[1, 'First'], [2, 'Second'], [3, 'Third']]);
  });

  it('joins unquoted words into one todo', async (t) => {
    const dir = await makeTempDir(t);
    const result = await runCli(['add', 'Walk', 'the', 'dog'], { cwd: dir });
    assert.equal(result.stdout, 'Added todo #1: Walk the dog\n');
  });

  it('exits 2 with a usage hint and creates no file when the text is missing', async (t) => {
    const dir = await makeTempDir(t);
    const result = await runCli(['add'], { cwd: dir });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /Error: Missing todo text\. Usage: node index\.js add "<text>"/);
    assert.deepEqual(await listDir(dir), []);
  });

  it('exits 2 for empty or whitespace-only text', async (t) => {
    const dir = await makeTempDir(t);
    for (const text of ['', '   ']) {
      const result = await runCli(['add', text], { cwd: dir });
      assert.equal(result.code, 2, `text ${JSON.stringify(text)} should be rejected`);
      assert.match(result.stderr, /Todo text cannot be empty/);
    }
    await assertNoTodosFile(dir);
  });
});

describe('list', () => {
  it('reports an empty list without creating todos.json', async (t) => {
    const dir = await makeTempDir(t);
    const result = await runCli(['list'], { cwd: dir });
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'No todos yet. Add one with: node index.js add "<text>"\n');
    await assertNoTodosFile(dir);
  });

  it('shows id, [ ] or [x], and text for each todo, plus a summary', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'Buy groceries', 'Walk the dog');
    await runCli(['complete', '2'], { cwd: dir });
    const result = await runCli(['list'], { cwd: dir });
    assert.equal(result.code, 0);
    assert.equal(result.stdout, '1. [ ] Buy groceries\n2. [x] Walk the dog\n\n2 todos: 1 done, 1 pending\n');
  });

  it('reports an empty list again after every todo is deleted', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'Only one');
    await runCli(['delete', '1'], { cwd: dir });
    const result = await runCli(['list'], { cwd: dir });
    assert.match(result.stdout, /^No todos yet\./);
  });

  it('exits 2 when given unexpected arguments', async (t) => {
    const result = await runCli(['list', 'all'], { cwd: await makeTempDir(t) });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /"list" takes no arguments, got: all/);
  });
});

describe('complete', () => {
  it('marks the todo as done and persists it', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'Buy groceries', 'Walk the dog');
    const result = await runCli(['complete', '1'], { cwd: dir });
    assert.equal(result.code, 0, result.stderr);
    assert.equal(result.stdout, 'Completed todo #1: Buy groceries\n');
    const { todos } = await readTodosFile(dir);
    assert.deepEqual(todos.map((todo) => todo.completed), [true, false]);
  });

  it('succeeds without changes when the todo is already completed', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'Buy groceries');
    await runCli(['complete', '1'], { cwd: dir });
    const result = await runCli(['complete', '1'], { cwd: dir });
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Todo #1 is already completed: Buy groceries\n');
  });

  it('exits 1 and suggests "list" when the id does not exist', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'Buy groceries');
    const result = await runCli(['complete', '99'], { cwd: dir });
    assert.equal(result.code, 1);
    assert.equal(result.stderr, 'Error: No todo with id 99.\nRun "node index.js list" to see existing ids.\n');
    assert.equal((await readTodosFile(dir)).todos[0].completed, false);
  });

  it('exits 1 on an empty list', async (t) => {
    const result = await runCli(['complete', '1'], { cwd: await makeTempDir(t) });
    assert.equal(result.code, 1);
    assert.match(result.stderr, /No todo with id 1\./);
  });

  it('exits 2 when the id is missing', async (t) => {
    const result = await runCli(['complete'], { cwd: await makeTempDir(t) });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /Missing todo id\. Usage: node index\.js complete <id>/);
  });

  for (const badId of ['abc', '0', '-1', '1.5', '1e2']) {
    it(`exits 2 for the invalid id "${badId}"`, async (t) => {
      const result = await runCli(['complete', badId], { cwd: await makeTempDir(t) });
      assert.equal(result.code, 2);
      assert.match(result.stderr, /Invalid id/);
    });
  }

  it('exits 2 when given more than one id', async (t) => {
    const result = await runCli(['complete', '1', '2'], { cwd: await makeTempDir(t) });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /"complete" takes exactly one id, got 2/);
  });
});

describe('delete', () => {
  it('removes the todo and keeps the others', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'First', 'Second', 'Third');
    const result = await runCli(['delete', '2'], { cwd: dir });
    assert.equal(result.code, 0, result.stderr);
    assert.equal(result.stdout, 'Deleted todo #2: Second\n');
    const { todos } = await readTodosFile(dir);
    assert.deepEqual(todos.map((todo) => todo.id), [1, 3]);
  });

  it('exits 1 when the id does not exist and leaves the file unchanged', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'First');
    const before = await readTodosFile(dir);
    const result = await runCli(['delete', '5'], { cwd: dir });
    assert.equal(result.code, 1);
    assert.match(result.stderr, /No todo with id 5\./);
    assert.deepEqual(await readTodosFile(dir), before);
  });

  it('exits 2 when the id is missing', async (t) => {
    const result = await runCli(['delete'], { cwd: await makeTempDir(t) });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /Missing todo id\. Usage: node index\.js delete <id>/);
  });

  it('exits 2 for a non-numeric id', async (t) => {
    const result = await runCli(['delete', 'first'], { cwd: await makeTempDir(t) });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /Invalid id "first"/);
  });
});

describe('full workflow', () => {
  it('add, complete, delete, and list work together across separate processes', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'Buy groceries', 'Walk the dog', 'Write report');
    assert.equal((await runCli(['complete', '3'], { cwd: dir })).code, 0);
    assert.equal((await runCli(['delete', '1'], { cwd: dir })).code, 0);
    await seed(dir, 'Call mom');

    const result = await runCli(['list'], { cwd: dir });
    assert.equal(
      result.stdout,
      '2. [ ] Walk the dog\n3. [x] Write report\n4. [ ] Call mom\n\n3 todos: 1 done, 2 pending\n',
    );
    assert.deepEqual(await listDir(dir), ['todos.json'], 'no lock or temp files should be left behind');
  });
});

