import assert from 'node:assert/strict';
import { mkdir, readFile, stat, utimes, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { describe, it } from 'node:test';
import { StorageError } from '../src/errors.js';
import { loadTodos, resolveTodosPath, saveTodos, updateTodos, withFileLock } from '../src/store.js';
import { addTodo, completeTodo } from '../src/todos.js';
import { SKIP_IF_ROOT, deadPid, listDir, makeTempDir, withReadOnlyDir } from './helpers.js';

const TODO = { id: 1, text: 'Buy groceries', completed: false, createdAt: '2026-01-02T03:04:05.678Z' };
const FAST_LOCK = { timeoutMs: 200, retryMs: 10 };

describe('resolveTodosPath', () => {
  it('points at todos.json inside the given directory', () => {
    assert.equal(resolveTodosPath('/work/project'), path.resolve('/work/project', 'todos.json'));
  });
});

describe('loadTodos', () => {
  it('returns an empty list when todos.json does not exist', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    assert.deepEqual(await loadTodos(file), { nextId: 1, todos: [] });
  });

  it('returns an empty list for an empty or whitespace-only file', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    await writeFile(file, '  \n');
    assert.deepEqual(await loadTodos(file), { nextId: 1, todos: [] });
  });

  it('reads a file that starts with a UTF-8 byte order mark', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    await writeFile(file, `\uFEFF${JSON.stringify({ nextId: 2, todos: [TODO] })}`);
    assert.deepEqual((await loadTodos(file)).todos, [TODO]);
  });

  it('rejects invalid JSON with the file path and leaves the file untouched', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    await writeFile(file, '{ not json');
    await assert.rejects(loadTodos(file), (error) => {
      assert.ok(error instanceof StorageError);
      assert.match(error.message, /is not valid JSON/);
      assert.ok(error.message.includes(file));
      return true;
    });
    assert.equal(await readFile(file, 'utf8'), '{ not json');
  });

  it('wraps read errors other than a missing file', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    await mkdir(file);
    await assert.rejects(loadTodos(file), { name: 'StorageError', message: /Could not read .*todos\.json: EISDIR/ });
  });
});

describe('saveTodos', () => {
  it('writes pretty-printed { nextId, todos } that loadTodos reads back', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    const state = { nextId: 2, todos: [TODO] };
    await saveTodos(file, state);
    assert.equal(await readFile(file, 'utf8'), `${JSON.stringify(state, null, 2)}\n`);
    assert.deepEqual(await loadTodos(file), state);
  });

  it('replaces the previous contents and leaves no temporary files', async (t) => {
    const dir = await makeTempDir(t);
    const file = resolveTodosPath(dir);
    await saveTodos(file, { nextId: 2, todos: [TODO] });
    await saveTodos(file, { nextId: 2, todos: [] });
    assert.deepEqual((await loadTodos(file)).todos, []);
    assert.deepEqual(await listDir(dir), ['todos.json']);
  });

  it('raises StorageError and cleans up when the directory is not writable', { skip: SKIP_IF_ROOT }, async (t) => {
    const dir = await makeTempDir(t);
    await withReadOnlyDir(dir, () =>
      assert.rejects(saveTodos(resolveTodosPath(dir), { nextId: 1, todos: [] }), {
        name: 'StorageError',
        message: /Could not write .*todos\.json: EACCES/,
      }),
    );
    assert.deepEqual(await listDir(dir), []);
  });
});

describe('updateTodos', () => {
  it('saves the new state when the mutation reports a change', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    const result = await updateTodos(file, (state) => addTodo(state, 'Buy groceries'));
    assert.equal(result.todo.id, 1);
    assert.equal((await loadTodos(file)).todos[0].text, 'Buy groceries');
  });

  it('does not rewrite the file when nothing changed', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    await saveTodos(file, { nextId: 2, todos: [{ ...TODO, completed: true }] });
    const past = new Date('2020-01-01T00:00:00Z');
    await utimes(file, past, past);
    const result = await updateTodos(file, (state) => completeTodo(state, 1));
    assert.equal(result.changed, false);
    assert.equal((await stat(file)).mtimeMs, past.getTime());
  });

  it('releases the lock and propagates the error when the mutation throws', async (t) => {
    const dir = await makeTempDir(t);
    const file = resolveTodosPath(dir);
    await assert.rejects(updateTodos(file, () => { throw new Error('mutation failed'); }), /mutation failed/);
    assert.deepEqual(await listDir(dir), []);
  });

  it('serializes concurrent in-process updates so no add is lost', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    const texts = Array.from({ length: 20 }, (_, index) => `Parallel ${index}`);
    await Promise.all(texts.map((text) => updateTodos(file, (state) => addTodo(state, text), { retryMs: 1 })));
    const { todos, nextId } = await loadTodos(file);
    assert.equal(todos.length, texts.length);
    assert.deepEqual(todos.map((todo) => todo.id).sort((a, b) => a - b), texts.map((_, index) => index + 1));
    assert.deepEqual(todos.map((todo) => todo.text).sort(), texts.toSorted());
    assert.equal(nextId, texts.length + 1);
  });
});

describe('withFileLock', () => {
  it('times out with a message naming the lock file when a live process holds it', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    await writeFile(`${file}.lock`, `${process.pid}\n`);
    let ran = false;
    await assert.rejects(
      withFileLock(file, async () => { ran = true; }, FAST_LOCK),
      { name: 'StorageError', message: /Timed out after 200 ms waiting for .*todos\.json\.lock/ },
    );
    assert.equal(ran, false);
  });

  it('takes over a lock whose owner process has exited', async (t) => {
    const dir = await makeTempDir(t);
    const file = resolveTodosPath(dir);
    await writeFile(`${file}.lock`, `${deadPid()}\n`);
    assert.equal(await withFileLock(file, async () => 'ran', FAST_LOCK), 'ran');
    assert.deepEqual(await listDir(dir), []);
  });

  it('takes over a lock older than staleMs even if its pid is alive', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    const lockPath = `${file}.lock`;
    await writeFile(lockPath, `${process.pid}\n`);
    const old = new Date(Date.now() - 60_000);
    await utimes(lockPath, old, old);
    assert.equal(await withFileLock(file, async () => 'ran', { ...FAST_LOCK, staleMs: 1000 }), 'ran');
  });

  it('writes the owner pid into the lock file while held', async (t) => {
    const file = resolveTodosPath(await makeTempDir(t));
    const contents = await withFileLock(file, () => readFile(`${file}.lock`, 'utf8'));
    assert.equal(contents, `${process.pid}\n`);
  });

  it('raises StorageError when the lock cannot be created', { skip: SKIP_IF_ROOT }, async (t) => {
    const dir = await makeTempDir(t);
    await withReadOnlyDir(dir, () =>
      assert.rejects(withFileLock(resolveTodosPath(dir), async () => {}), {
        name: 'StorageError',
        message: /Could not create lock file .*todos\.json\.lock: EACCES/,
      }),
    );
  });
});

