import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { STATUS_MARKERS, formatTodo, formatTodoList } from '../src/format.js';

function todo(id, text, completed = false) {
  return { id, text, completed, createdAt: '2026-01-02T03:04:05.678Z' };
}

describe('formatTodo', () => {
  it('shows a pending todo with an empty box', () => {
    assert.equal(formatTodo(todo(1, 'Buy groceries')), '1. [ ] Buy groceries');
  });

  it('shows a completed todo with [x]', () => {
    assert.equal(formatTodo(todo(2, 'Walk dog', true)), '2. [x] Walk dog');
  });

  it('left-pads the id to the requested width', () => {
    assert.equal(formatTodo(todo(3, 'Pad me'), 3), '  3. [ ] Pad me');
  });

  it('exposes the markers the spec requires', () => {
    assert.deepEqual(STATUS_MARKERS, { done: '[x]', pending: '[ ]' });
  });
});

describe('formatTodoList', () => {
  it('lists each todo with id, marker and text, followed by a summary', () => {
    const output = formatTodoList([todo(1, 'Buy groceries'), todo(2, 'Walk dog', true)]);
    assert.equal(output, ['1. [ ] Buy groceries', '2. [x] Walk dog', '', '2 todos: 1 done, 1 pending'].join('\n'));
  });

  it('aligns markers when ids have different widths', () => {
    const lines = formatTodoList([todo(9, 'Nine'), todo(10, 'Ten')]).split('\n');
    assert.equal(lines[0], ' 9. [ ] Nine');
    assert.equal(lines[1], '10. [ ] Ten');
  });

  it('uses the singular noun for exactly one todo', () => {
    assert.match(formatTodoList([todo(1, 'Only')]), /^1 todo: 0 done, 1 pending$/m);
  });

  it('orders by id without reordering the caller array', () => {
    const input = [todo(3, 'C'), todo(1, 'A')];
    const lines = formatTodoList(input).split('\n');
    assert.deepEqual(lines.slice(0, 2), ['1. [ ] A', '3. [ ] C']);
    assert.deepEqual(input.map((t) => t.id), [3, 1]);
  });

  it('handles an empty list with a zero summary', () => {
    assert.equal(formatTodoList([]), '\n0 todos: 0 done, 0 pending');
  });

  it('formats 200,000 todos without overflowing the call stack', () => {
    const many = Array.from({ length: 200_000 }, (_, index) => todo(index + 1, 'x'));
    const lines = formatTodoList(many).split('\n');
    assert.equal(lines.length, 200_002);
    assert.equal(lines[0], '     1. [ ] x');
  });
});

