29	/**
30	 * Runs one CLI command. Expected failures are printed to stderr; this never
31	 * throws for them.
32	 * @param {string[]} argv arguments after `node index.js`
33	 * @param {RunOptions} [options]
34	 * @returns {Promise<number>} process exit code, see EXIT_CODES
35	 */
36	export async function run(argv, options = {}) {
37	  const { cwd = process.cwd(), stdout = process.stdout, stderr = process.stderr, now = () => new Date(), lock } = options;
